{
  "system": "Amdocs Kenan",
  "feature": "Offline Rating for Post-paid Subscribers",
  "description": "Amdocs Kenan supports file-based offline rating for post-paid subscribers. The rating engine uses a sophisticated model based on customer and product offering characteristics, while supporting in-line promotions and charge monitoring for notification purposes. The engine delivers high performance and supports diverse interpretations of chargeable events.",
  "components": {
    "message_processing_system": {
      "name": "Message Processing System (MPS)",
      "purpose": "Calculates usage charges for customers and sometimes foreign accounts",
      "tasks": [
        "Collect usage files from a network mediation layer",
        "Parse each file to determine type, time, duration, and other properties of usage events",
        "Guide each usage event to an Amdocs Kenan or external account",
        "Rate each usage event and store the usage charge and related information in the database",
        "Export rated usage events for foreign carriers and reseller usage events"
      ]
    }
  },
  "rating_capabilities": {
    "attributes_supported": [
      "duration",
      "volume",
      "location",
      "time_of_day",
      "jurisdiction",
      "zone_class",
      "distance_band",
      "bill_class",
      "provider_class",
      "product_type",
      "equipment_class_code",
      "service_code"
    ],
    "features": [
      "Supports multiple combinations of rating attributes",
      "Allows input in one unit and rating in a different unit",
      "Supports minimum charge and per-unit charge configuration",
      "Supports pre-rated usage to be re-rated or loaded without applying additional charges"
    ]
  },
  "billing_and_discounts": {
    "standard_processing": "During invoice processing, discounts and allowances are applied to usage collected in the current billing run, even if the usage is late.",
    "late_usage_behavior": "Late usage from a previous month consumes allowance from the current month by default.",
    "special_late_usage_handling": {
      "description": "Supports configuration to apply discounts based on the event transaction date instead of the billing date.",
      "impact": [
        "Recalculates discounts applied to previous invoices",
        "Generates discount and allowance adjustments when reassessment occurs"
      ]
    }
  },
  "notifications": {
    "purpose": "Allows service providers to track spending across thresholds and usage profiles",
    "supported_levels": [
      "specific usage types",
      "specific products or services",
      "customer account level",
      "corporate hierarchy level"
    ]
  }
}

